import{_ as n,c as a,o as t,a2 as r}from"./chunks/framework.CJYbxa8B.js";const i="/Wahllokalsystem/relationshipOfUIsToElectionProcess.drawio.png",p=JSON.parse('{"title":"About","description":"","frontmatter":{},"headers":[],"relativePath":"about/index.md","filePath":"about/index.md"}'),s={name:"about/index.md"};function d(l,e,o,h,u,m){return t(),a("div",null,e[0]||(e[0]=[r('<h1 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h1><p>In diesem Repository wollen wir das Wahllokalsystem der Landeshauptstadt München, das initial zur Bundestagswahl 2017 eingeführt wurde, veröffentlichen. Anlass dafür ist eine geplante Lifecyclemaßnahme. Da wir im Rahmen dieser Maßnahme die gesamte Anwendung betrachten, bot es sich an entsprechend der <a href="https://opensource.muenchen.de/de/principles.html#rechtliche-und-politische-vorgaben" target="_blank" rel="noreferrer">OpenSource-Strategie</a> der Landeshauptstadt München, die Anwendung OpenSource zu stellen.</p><p>Am Ende soll die Anwendung für Interessierte vollständig zur Verfügung stehen.</p><h2 id="was-kann-die-software" tabindex="-1">Was kann die Software <a class="header-anchor" href="#was-kann-die-software" aria-label="Permalink to &quot;Was kann die Software&quot;">​</a></h2><p>Der Hauptfokus der Software liegt auf den Handlungen am Wahltag. Sie unterstützt bei der Eröffnung des Wahllokals, indem man z.B. anhand einer Checkliste prüfen kann, dass alle notwendigen Materialien für die Durchführung vorhanden sind. Während der Zeit der Stimmabgabe wird übermittelt, wie viele Wähler*innen bereits im Wahllokal waren. Des Weiteren werden über die Software wahlrelevante Vorkommnisse dokumentiert.</p><p>Außerdem wird zu definierten Zeitpunkten abgefragt, welche Mitglieder des Wahlvorstandes im Wahllokal anwesend sind. So wird sichergestellt, dass das Gremium zu jeder Zeit ausreichend besetzt ist.</p><p>Während der Stimmauszählung, und der damit verbundenen Erstellung der Niederschrift, unterstützt das System den Wahlvorstand bei der korrekten Erfassung der Daten. Dazu gibt es zahlreiche Regeln und Konsistenzprüfungen, die dem Wahlvorstand Feedback geben, ob die erfassten Daten korrekt sind.</p><p>Das Wahlamt kann über das System den Wahlbezirken wichtige Informationen zukommen lassen.</p><p><img src="'+i+'" alt="Übersicht der Funktionen des Wahllokalsystems im zeitlichen Kontext einer Wahl"><br><em>Übersicht der Funktionen des Wahllokalsystems im zeitlichen Kontext einer Wahl</em></p>',9)]))}const f=n(s,[["render",d]]);export{p as __pageData,f as default};
